 rebuild(){this.grid=Array.from({length:HEIGHT},()=>Array(WIDTH).fill(0));for(const r of this.state.rooms){const bx=2+r.col*8,by=2+r.row*8;for(let y=1;y<6;y++)for(let x=1;x<6;x++)this.grid[by+y][bx+x]=1;
  for(const [dc,dr] of [[1,0],[0,1]]){if(!this.state.rooms.some(o=>o.col===r.col+dc&&o.row===r.row+dr))continue;for(let i=6;i<=8;i++)this.grid[by+(dr?i:3)][bx+(dc?i:3)]=1;}}
 }
