 path(a,b){const sx=Math.round(a.x),sy=Math.round(a.y),tx=Math.round(b.x),ty=Math.round(b.y);if(!this.walkable(tx,ty)||!this.walkable(sx,sy))return [];const queue=[[sx,sy]],seen=new Map([[`${sx},${sy}`,null]]);let k=0;
  while(k<queue.length){const [x,y]=queue[k++];if(x===tx&&y===ty){let p=[x,y],out=[];while(p){out.unshift({x:p[0],y:p[1]});p=seen.get(p.join(','))}return out.slice(1)}for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,key=`${nx},${ny}`;if(this.grid[ny]?.[nx]&&!seen.has(key)){seen.set(key,[x,y]);queue.push([nx,ny])}}}return [];
 }
