 build(col,row,type){const s=this.state;if(s.phase!=='prepare'||s.paused)return {ok:false,message:'Chỉ xây dựng khi đang chuẩn bị và không tạm dừng.'};if(!ROOMS[type]||['entrance','treasure'].includes(type))return {ok:false,message:'Bản thiết kế không hợp lệ.'};if(col<0||col>=COLS||row<0||row>=ROWS||s.rooms.some(r=>r.col===col&&r.row===row))return {ok:false,message:'Ô xây dựng không hợp lệ.'};if(!s.rooms.some(r=>Math.abs(r.col-col)+Math.abs(r.row-row)===1))return {ok:false,message:'Phòng mới phải kề một phòng hiện có.'};if(s.rooms.length>=10)return {ok:false,message:'Tầng này có tối đa 10 phòng.'};if(s.gold<ROOMS[type].cost)return {ok:false,message:'Không đủ vàng.'};s.gold-=ROOMS[type].cost;s.statistics.spent+=ROOMS[type].cost;this.addRoom(col,row,type);this.rebuild();this.log(`Đã xây ${ROOMS[type].name}.`);this.emit();return {ok:true}}
 summon(species,x,y){const costs={goblin:25,skeleton:30,slime:20},s=this.state;if(s.phase!=='prepare'||s.paused)return {ok:false,message:'Chỉ triệu hồi trong giai đoạn chuẩn bị, khi không tạm dừng.'};if(!(species in costs)||!this.walkable(x,y))return {ok:false,message:'Hãy chọn nền phòng.'};if(s.entities.filter(e=>e.faction==='monster').length>=15)return {ok:false,message:'Đã đạt sức chứa 15 cư dân.'};if(s.mana<costs[species])return {ok:false,message:'Không đủ mana.'};s.mana-=costs[species];const pool=['violent','fearful','guardian','frenzy','greedy','forsaken','opportunist','proud','camaraderie'];const e=this.spawn(species,'monster',Math.round(x),Math.round(y),`${SPECIES[species].name} ${s.id+1}`,[pool[Math.floor(this.random()*pool.length)]]);this.log(`${e.name} đã gia nhập hầm ngục.`);this.emit();return {ok:true,entity:e}}
 start(){if(this.state.phase!=='prepare')return {ok:false,message:'Cuộc thám hiểm chưa sẵn sàng.'};if(!this.connected())return {ok:false,message:'Kho báu phải có đường đi từ lối vào.'};const s=this.state;s.phase='battle';s.paused=false;s.speed=1;s.battleTime=0;s.statistics.downed=0;s.statistics.escaped=0;const p=center(s.rooms.find(r=>r.type==='entrance'));const types=['knight','rogue','mage','priest'];const names=['Arthur','Ren','Elara','Seren'];const charms=[['blessed','guardian'],['greedy','fearful','opportunist'],['violent'],['guardian','camaraderie']];
  for(let i=0;i<Math.min(7,2+Math.ceil(s.wave/2));i++){const old=s.reports.find(r=>r.species===types[i%4]&&r.survived&&!r.returned);const e=this.spawn(types[i%4],'hero',p.x+(i%2)*.35,p.y+Math.floor(i/2)*.35,old?old.name:names[i%4]+(i>3?' II':''),charms[i%4]);if(old){old.returned=true;e.level=old.level+1;e.memory=old.memory;e.maxHp+=12;e.hp=e.maxHp;this.log(`${e.name} đã trở lại, mang theo ký ức về hầm ngục.`)}else e.level=1+Math.floor((s.wave-1)/2);e.maxHp+=Math.floor((s.wave-1)*6);e.hp=e.maxHp;}
  this.log(`Cuộc thám hiểm ${s.wave} bắt đầu. Đoàn mạo hiểm đã đến!`,'warning');this.emit();return {ok:true}}
 heal(e,amount){if(e.status!=='active'||e.charms.includes('forsaken'))return 0;const n=Math.min(amount,e.maxHp-e.hp);e.hp+=n;return n}
 usedSlots(e){return e.inventory.length+(e.potions||0)+(this.state.treasure.carrier===e.id?1:0)}
